-- =====================================================================
-- SmarterVote.ca — expansion seed: municipalities
--
-- 265 Ontario municipalities (2026-10-26 election) + British Columbia
-- (2026-10-24 provincial election; its 93 electoral districts are modelled
-- as races under this one row in 26/27).
--
-- coverage_status 'partial' is honest: listings tier only so far — names,
-- races and candidates, no sourced positions yet (18 municipalities get the
-- full issue taxonomy in 28).
--
-- official_url: first source_url seen for the municipality in the staged
-- roster. BC uses https://elections.bc.ca.
--
-- Run AFTER 24. Idempotent: on conflict (slug) do nothing — existing rows
-- (including Huntsville) are never touched.
-- =====================================================================

begin;

on conflict (slug) do nothing;

commit;

-- VERIFY: expect 265 ON + 1 BC, zero Huntsville impact
select province, count(*) as municipalities
from municipalities
where slug <> 'huntsville'
group by province
order by province;
